from h34 import *
M=mcq;F=tf;S=short;N=num
b='<text x="360" y="26" text-anchor="middle" font-size="18" font-weight="bold">One brick, three views</text>'
b+='<rect x="40" y="70" width="180" height="90" fill="#e8a87c" stroke="#222" stroke-width="3"/><text x="130" y="190" text-anchor="middle">Top view (long and wide)</text>'
b+='<rect x="270" y="70" width="180" height="45" fill="#e8a87c" stroke="#222" stroke-width="3"/><text x="360" y="145" text-anchor="middle">Front view (long and short)</text>'
b+='<rect x="520" y="70" width="90" height="45" fill="#e8a87c" stroke="#222" stroke-width="3"/><text x="565" y="145" text-anchor="middle">Side view (short end)</text>'
b+='<text x="360" y="230" text-anchor="middle" font-size="15" fill="#555">The same brick looks different when we look from different places.</text>'
svgfile('c4m-hide-views.svg',720,260,b)
chapter(4,'maths','hide-and-seek','Hide and Seek',
 ('Where are you hiding?','Rani, Mini, Bholu and Jagat are playing hide and seek. Rani looks for the others, but from where she stands she cannot see everyone. Someone sitting on a tree sees much more! In this chapter we learn how things look from different places, and how to find our way using positions, grids and maps.'),
 [('Looking from different places',['The children are playing hide and seek. Rani counts while the others hide near the hut, behind a tree and in other places.','If Rani looks one way, she can see only the children in front of her. Someone who looks from the top of a tree can see much more.','So what we see depends on where we stand and in which direction we look.','In Scene 4, Mini is on high ground, so she can see all the children playing the game.']),
  ('Top view, front view and side view',['Bholu is amazed to see how the tree looks from the top. From the top the tree looks like a round green circle, but from the front we see its trunk and leaves.','Mini, Bholu and Rani each draw the same brick, but their drawings are different because each is looking from a different side.','The view from above is called the top view, the view from the face is called the front view, and the view from the side is called the side view.','For a brick, the top view shows the long and wide face, and the front view and the side view show the thinner faces.','You can draw a chair, a pencil, a bottle or a birthday cap from the top, front and side, and ask a friend to match the drawing with the object.']),
  ('Building with matchboxes',['Jagat and Mini make buildings from empty matchboxes and draw them from the front, back and top.','A building looks different from each side, because boxes can hide each other.','Try building your own, draw its views and challenge a friend to match the pictures to the building.']),
  ('Where is Jagat? Position in the class',['Jagat’s cat looks through the window and tries to find him in the classroom.','We can say where something is using rows and desks. Jagat sits on the third desk in the first row.','To find a bag or a notebook, we count the row first and then the desk in that row, such as the middle desk of the second row.','Giving the row and the place makes the position clear, so that anyone can find the object.']),
  ('The grid game',['A grid has rows and columns. Rows go across, and columns go up and down.','Rani gives clues to Bholu. Put a ball at the bottom left corner, which is first row and first column.','The eraser goes in the top right corner and the pencil in the top left. The apple is in the middle, in row 2 and column 2.','The water bottle goes in the third row and second column, which is the top middle square, because in the book’s grid row 1 is at the bottom and row 3 is at the top.','A clue says where to put something using row and column, and we may count rows from the bottom as in the picture.']),
  ('Treasure hunt on a grid',['In the treasure hunt, one player thinks of an object on a 4 by 4 grid and the other player moves to it.','We start from the starting point and move steps to the right or left and up or down. No diagonal moves are allowed.','Mini takes 4 steps to the right, then 2 steps left and 1 step up. The final place is found by adding the right steps and subtracting the left steps.','Different paths can reach the same object. The path with the fewest steps is the shortest path.','To say a path we use words, such as from the start I moved 3 steps right and then 2 steps up.']),
  ('The drone and the sight map',['Gyan’s drone takes a picture from high above the school. From the top we can see the playground, the walls, the parks and the buildings.','A sight map is like a picture from the top. It shows where important places are, such as the library, hall, stage, IT room and medical room.','We can trace a path from one place to another, for example from the Grade 4 classroom to the stage, and often there is more than one route.','The shortest route is the one that passes the fewest places or is the shortest length, and we can compare routes by counting steps.','To help someone, give directions with words like left, right, straight, turn and near.','You can draw a sight map from your school gate to your classroom and show the places that matter.'])],
 [('Mini moves 4 steps right and then 2 steps left from the start of the grid. How far is she from the start?',[('Right moves go one way and left moves go back the other way.','Draw a line to see it.'),('4 steps right, then 2 steps back makes 4 − 2 = 2.','Subtract the steps back.'),('She is 2 steps to the right of the start.','Check by drawing.')]),
  ('A pencil is in the top left corner of a 3 by 3 grid. Where do the eraser and ball go if the eraser is top right and the ball is bottom left?',[('Rows go across and columns go down.','Corners are the 4 corners of the grid.'),('Top left has the pencil, top right has the eraser.','Same row, different columns.'),('Bottom left, the first column in the bottom row, has the ball.','Each object has its own place.')])],
 ('Explain how the view of an object changes and how we find places on a grid or map.',['The view changes with the side we look from','Top, front and side views show different faces','On a grid we use rows, columns and steps','A map shows places from the top and helps us choose a route'],['An object looks the same from every side','Diagonal moves are allowed on the grid','A map is a picture from the front']),
 ['Things look different from the top, front and side.','Rows go across and columns go up and down, and they tell exactly where something is.','On a grid we move up, down, left and right.','A sight map is a view from the top that helps us find routes.','The shortest route has the fewest steps.'],
 [M('1',1,'The view of an object from above is called the ___.','top view',[('front view','The front view is from the face'),('side view','The side view is from one side')],'Top means above.'),
  M('2',1,'Why do three drawings of the same brick look different?','Each child looks from a different side',[('The brick changes shape','The brick stays the same'),('The pencils are different','The reason is the view')],'We see different faces.'),
  M('3',1,'In a grid, rows go ___.','across',[('up and down','That is columns'),('diagonally','Rows are straight across')],'Rows go from left to right.'),
  M('4',1,'Which child can see most of the other children in hide and seek?','The one who looks from a high place',[('The one who looks at a wall','The wall blocks the view'),('The one with closed eyes','They cannot see anything')],'Looking from above shows more.'),
  M('5',2,'A ball is in the bottom left corner of a grid. Which row and column is it?','First row and first column',[('Third row and third column','That is the top right corner'),('Second row and second column','That is the middle')],'Rows are counted from the bottom in the book’s grid.'),
  M('6',2,'On a grid, which moves are allowed in the treasure hunt?','Up, down, left and right',[('Diagonal moves','Diagonals are not allowed'),('Jumping over squares','We move one step at a time')],'Only straight steps.'),
  M('7',2,'Mini takes 4 steps right and then 2 steps left. How far from the start?','2 steps right',[('6 steps right','The 2 steps left take her back'),('2 steps left','She moved more to the right')],'4 − 2 = 2.'),
  M('8',2,'A sight map of the school is a view from the ___.','top',[('front','Maps show from above'),('side','Maps show from above')],'A map is like a drone picture.'),
  N('9',2,'How many small squares are there in a grid with 3 rows and 3 columns?',9,'3 × 3 = 9.',[(6,'That adds 3 + 3 instead of multiplying'),(3,'That is only one row')],'squares'),
  M('10',2,'How do we find the shortest route on a map?','Choose the route with the fewest steps',[('Choose the route with the most turns','More turns can make it longer'),('Choose any route','We must compare the routes')],'Count steps for each route.'),
  F('11',2,'The same object can have different top, front and side views.',True,'Each view shows a different face.'),
  F('12',3,'A path on a grid can go diagonally in the treasure hunt.',False,'Only up, down, left, right.')],
 svgs=[('c4m-hide-views','Three rectangles showing the top, front and side views of a brick.','The same brick looks different from the top, front and side.')],
 keep=['grid','top view','front view','side view'])
